/*
 * os_config.h -- OS identity configuration (fallback defaults)
 *
 * DO NOT EDIT THIS FILE to rebrand the OS. Edit config.mk in the project
 * root instead -- `make` generates build/generated/os_config.h from it,
 * and that file takes precedence over this one in the include path.
 * This copy only provides defaults so the sources also compile when the
 * generated header has not been created yet.
 *
 * Kernel originally created by mayshecry.
 */
#ifndef OS_CONFIG_H
#define OS_CONFIG_H

#ifndef OS_NAME
#define OS_NAME "MyOS"
#endif
#ifndef OS_NAME_LOWER
#define OS_NAME_LOWER "myos"
#endif
#ifndef OS_VERSION
#define OS_VERSION "1.0"
#endif
#ifndef OS_CODENAME
#define OS_CODENAME "Base"
#endif
#ifndef OS_VENDOR
#define OS_VENDOR "YourName"
#endif
#ifndef OS_HOSTNAME
#define OS_HOSTNAME "myos-pc"
#endif
#ifndef OS_DEFAULT_USER
#define OS_DEFAULT_USER "user"
#endif
#ifndef OS_SHELL_NAME
#define OS_SHELL_NAME "shell"
#endif

/* Kernel authorship credit -- kernel originally created by mayshecry. */
#ifndef KERNEL_AUTHOR
#define KERNEL_AUTHOR "mayshecry"
#endif
#define KERNEL_CREDIT "Kernel created by " KERNEL_AUTHOR

#ifndef OS_WALLPAPER_TOP
#define OS_WALLPAPER_TOP 0xFF0B5FA5u
#endif
#ifndef OS_WALLPAPER_BOTTOM
#define OS_WALLPAPER_BOTTOM 0xFF083B66u
#endif

#ifndef CONFIG_ENABLE_ATA
#define CONFIG_ENABLE_ATA 1
#endif
#ifndef CONFIG_ENABLE_AUDIO
#define CONFIG_ENABLE_AUDIO 1
#endif
#ifndef CONFIG_ENABLE_NETWORK
#define CONFIG_ENABLE_NETWORK 1
#endif

#endif /* OS_CONFIG_H */
